struct Base {
    int base_val = 1;
};

struct Derived : Base {
    int base_val = 2; // Hides Base::base_val

    void lookup_test() {
        // Lookup starts at Derived scope
        int d = base_val;  // d == 2 (Derived::)

        // Base scope must be qualified
        int b = Base::base_val; // b == 1

        // Accessing global scope (if available) requires ::
    }
};
